import {subjects,collections,SOURCES} from './catalog.js';
import {contact,contactOptions,whatsappURL} from './contact.js';
import {createClassroom} from './classroom.js';
import * as science from './data/physics.js';
import {questionDiagram,symbolKey} from './data/diagrams.js';
import * as maths from './data/mathematics.js';
import * as accounting from './data/accounting.js';
import * as mathslit from './data/mathslit.js';
import {makeQuestion,parseAnswer} from './data/questions.js';
import {videos as scienceVideos} from './data/physics-videos.js';
import {videos as mathsVideos} from './data/mathematics-videos.js';
import {papers as sciencePapers} from './data/physics-papers.js';
import {papers as mathsPapers} from './data/mathematics-papers.js';
import {pastPapers as accountingBank} from './data/accounting-papers.js';
import {pastPapers as mathslitBank} from './data/mathslit-papers.js';
import * as scienceLabs from './data/physics-labs.js';
import * as mathsLabs from './data/mathematics-labs.js';
const modules={'physical-sciences':science,mathematics:maths,accounting,'maths-literacy':mathslit};
const deepLinks={'physical-sciences':'../quantum-jump/',mathematics:'../plot-twist/',accounting:'../accounting/','maths-literacy':'../maths-literacy/'};
for(const s of subjects){if(modules[s.id]){s.topics=modules[s.id].topics;s.deep=true;}for(const t of s.topics){t.subject=s.id;}}
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const parse=(s,f)=>{try{return JSON.parse(s)??f}catch{return f}};
const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const defaults=()=>({version:1,profile:{name:'',goal:''},pins:['mathematics','physical-sciences','life-sciences','accounting','language-english','geography'],completed:[],saved:[],notes:[],sessions:[],scores:[],resources:[],settings:{theme:'light',large:false,motion:false,contrast:false},focusMinutes:0,visits:[],last:null});
let stored;try{stored=parse(localStorage.getItem('study-zone-v1'),null)}catch{}
let state={...defaults(),...(stored&&stored.version===1?stored:{})};
state.settings={...defaults().settings,...state.settings};
for(const k of ['pins','completed','saved','notes','sessions','scores','resources','visits'])if(!Array.isArray(state[k]))state[k]=defaults()[k];
if(!state.profile||typeof state.profile!=='object')state.profile=defaults().profile;
const main=$('#main');let route=[],currentQuestion=null,revealed=0,choice=null,quizChecked=false,flashIndex=0,flashFlipped=false,toastTimeout,searchGroup='All subjects',practiceSubject='mathematics';
const timer={remaining:1500,run:false,end:0,total:1500,kind:'Focus',credited:false};
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Africa/Johannesburg'});
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('en-ZA',{day:'numeric',month:'short'});
const subject=id=>subjects.find(s=>s.id===id);
const topic=(s,id)=>s?.topics.find(t=>t.id===id);
const key=(s,t)=>s.id+':'+t.id;
const b=(text,action,extra='',cls='button')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const link=(text,url,cls='button secondary',external=false)=>`<a class="${cls}" href="${esc(url)}"${external?' target="_blank" rel="noopener"':''}>${text}</a>`;
const options=(list,value)=>list.map(x=>`<option value="${esc(x.id??x)}"${(x.id??x)===value?' selected':''}>${esc(x.name??x)}</option>`).join('');
const subjectOptions=id=>options(subjects,id);
const empty=(title,text,button='')=>`<div class="empty"><h3>${title}</h3><p>${text}</p>${button}</div>`;
const head=(title,text,eyebrow='STUDY ZONE',actions='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${text}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;
const svgFlower='<svg viewBox="0 0 310 320" aria-hidden="true"><g transform="rotate(8 155 160)"><ellipse cx="158" cy="281" rx="107" ry="16" fill="#c8d7ba"/><rect x="57" y="60" width="196" height="209" rx="15" fill="#fffaf0" stroke="#45674c" stroke-width="2"/><rect x="46" y="48" width="196" height="209" rx="15" fill="#fffaf0" stroke="#45674c" stroke-width="2"/><path d="M75 48v209" stroke="#c1d1b6" stroke-width="2"/><path d="M94 91h109M94 103h78M94 205h105M94 219h83" stroke="#c6d1b9" stroke-width="4" stroke-linecap="round"/><path d="m103 162 27 26 51-64" fill="none" stroke="#4b7550" stroke-width="9" stroke-linecap="round" stroke-linejoin="round"/><circle cx="211" cy="59" r="38" fill="#dbe7ab" stroke="#4b7550" stroke-width="1.5"/><path d="m196 58 11 11 19-22" fill="none" stroke="#4b7550" stroke-width="4" stroke-linecap="round"/><g transform="rotate(-12 48 137)"><rect x="6" y="111" width="91" height="53" rx="8" fill="#f5d7bb" stroke="#b49271"/><text x="51" y="143" text-anchor="middle" fill="#6c4b2f" font-family="Georgia" font-size="23">x + you</text></g><g transform="rotate(-13 235 231)"><rect x="186" y="210" width="110" height="49" rx="8" fill="#dce8e9" stroke="#93b3b0"/><text x="242" y="241" text-anchor="middle" fill="#335b51" font-family="Georgia" font-size="18">= possible</text></g><path d="M265 102v22m-11-11h22M25 218v18m-9-9h18" stroke="#628554" stroke-width="2" stroke-linecap="round"/><circle cx="31" cy="65" r="4" fill="#e2bc82"/><circle cx="275" cy="175" r="5" fill="#9bb183"/></g></svg>';
function save(){try{localStorage.setItem('study-zone-v1',JSON.stringify(state));classroom.syncSummary();return true}catch{toast('This browser could not save your changes. Export a backup to keep your work.');return false}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function modal(html){$('#dialog-body').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal();setTimeout(()=>$('#dialog-body input, #dialog-body select, #dialog-body button')?.focus(),40)}
function close(){$('#dialog').close()}
function safeURL(value){try{const u=new URL(value,location.href);return /^https?:$/.test(u.protocol)?u.href:''}catch{return''}}
function download(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function syncMenu(){const small=matchMedia('(max-width:650px)').matches;$('#sidebar').inert=small&&!document.body.classList.contains('menu-open')}
function applySettings(){syncMenu();const s=state.settings;document.body.classList.toggle('dark',s.theme==='dark');document.body.classList.toggle('reading-wide',!!s.large);document.body.classList.toggle('low-motion',!!s.motion);document.body.classList.toggle('high-contrast',!!s.contrast);$('#avatar').textContent=(state.profile.name||'S').slice(0,1).toUpperCase();$('#profile-label').innerHTML=state.profile.name?`${esc(state.profile.name)}<small>Your personal study space</small>`:'Make this space yours<small>A personal study profile</small>'}
function profileModal(){modal(`<span class="eyebrow">YOUR OWN LITTLE CORNER</span><h2>Make yourself at home.</h2><p>A nickname is all you need. Your device profile, progress and notes stay here unless you choose to save a private online copy. Sign in from My account to use the shared classroom.</p><form id="profile-form"><label>What should we call you?<input name="name" maxlength="40" value="${esc(state.profile.name)}" placeholder="Your name or nickname" autocomplete="nickname"></label><label>One thing you are working towards<input name="goal" maxlength="160" value="${esc(state.profile.goal)}" placeholder="A little more confident with maths…"></label><button class="button" type="submit">This is my space ↗</button></form>`)}
function progress(s){return Math.round(s.topics.filter(t=>state.completed.includes(key(s,t))).length/s.topics.length*100)||0}
function subjectCard(s){const pinned=state.pins.includes(s.id);return`<article class="subject-card"><div class="subject-card-head"><a href="#subject/${s.id}" class="subject-symbol" aria-label="Open ${esc(s.name)}">${esc(s.icon)}</a>${b(pinned?'♥':'♡','pin',`data-id="${s.id}" aria-label="${pinned?'Unpin':'Pin'} ${esc(s.name)}" aria-pressed="${pinned}"`,'pin-button')}</div><a href="#subject/${s.id}"><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p></a><div class="subject-card-bottom"><span>${s.topics.length} topic${s.topics.length===1?'':'s'} · ${progress(s)}% explored</span><a href="#subject/${s.id}" aria-label="Study ${esc(s.name)}">↗</a></div><div class="progress-track"><span style="width:${progress(s)}%"></span></div></article>`}
function cards(list){return list.map(subjectCard).join('')}
function visit(s,t){state.last={subject:s.id,topic:t?.id};if(!state.visits.includes(today()))state.visits.push(today());save()}
function dashboard(){const list=state.pins.map(subject).filter(Boolean);const next=state.sessions.filter(x=>!x.done&&x.date>=today()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).slice(0,3);const date=new Date().toLocaleDateString('en-ZA',{weekday:'short',day:'numeric',month:'long',timeZone:'Africa/Johannesburg'});return`<div class="welcome-row"><h2>Hello, ${esc(state.profile.name||'bright mind')} <span aria-hidden="true">✳</span></h2><span class="date-pill"><i class="date-dot"></i>${date}</span></div><div class="hero-grid"><section class="hero"><div class="hero-copy"><div class="eyebrow">YOUR MATRIC. YOUR PACE. YOUR POSSIBILITIES.</div><h1>Big dreams.<br><em>Little steps.</em></h1><p>A whole world of subjects. One space to make sense of it all. Let’s find your next little breakthrough.</p><div class="hero-actions">${link('Find my subject <span>↗</span>','#subjects','button')}${link('Make a study plan','#planner','button soft')}</div><div class="hero-foot">✦ &nbsp; Come as you are. Start where you are.</div></div><div class="hero-art">${svgFlower}</div></section><aside class="today-card"><div class="today-head"><span class="eyebrow">A LITTLE DIRECTION</span><span>↗</span></div><h3>One thing<br>at a time.</h3>${next.length?next.map(x=>`<div class="daily-task"><span class="task-check">○</span><div>${esc(x.title)}<small>${dateLabel(x.date)} · ${esc(x.time)} · ${esc(subject(x.subject)?.name||'Personal study')}</small></div></div>`).join(''):`<div class="daily-task"><span class="task-check">1</span><div>Pick a subject<small>Start with the bit that feels a little wobbly.</small></div></div><div class="daily-task"><span class="task-check">2</span><div>Try one question<small>Your first attempt can be messy.</small></div></div><div class="daily-task"><span class="task-check">3</span><div>Notice a little progress<small>Every small step counts.</small></div></div>`}${link('Open my plan ↗','#planner','text-link')}</aside></div><div class="stats-strip"><div class="stat"><span class="stat-icon">▦</span><div><strong>${subjects.length}</strong><small>subject spaces to explore</small></div></div><div class="stat"><span class="stat-icon">✓</span><div><strong>${state.completed.length}</strong><small>topics explored</small></div></div><div class="stat"><span class="stat-icon">✎</span><div><strong>${state.scores.length}</strong><small>practice attempts checked</small></div></div><div class="stat"><span class="stat-icon">◷</span><div><strong>${state.focusMinutes}</strong><small>focused minutes</small></div></div></div><div class="section-heading"><div><h2>Your little subject universe</h2><p>Pin your subjects. Make this space feel like you.</p></div>${link('Explore all subjects ↗','#subjects','text-link')}</div><div class="subject-grid">${cards(list.slice(0,6))||empty('Your universe starts here.','Pin subjects from the library to bring them onto your home base.',link('Choose subjects','#subjects','button'))}</div><div class="lower-grid"><section class="feature-card green"><span class="eyebrow">THE PRACTICE STUDIO</span><span class="feature-flower" aria-hidden="true">✳</span><h2>Less “I can’t”.<br>More “let me try”.</h2><p>Try a question, unfold the working and learn from the bits that didn’t quite land. No pressure. Just practice.</p>${link('Try a little practice ↗','#practice','button soft')}</section><section class="feature-card"><span class="eyebrow">THE PAPER TRAIL</span><h2>Your future self<br>will thank you.</h2><p>Find official papers and marking guidelines, practise under exam conditions and keep track of what needs another look.</p>${link('Find a past paper ↗','#papers','text-link')}</section></div><div class="calm-strip"><p><span>☁</span> Brain feeling a little full? You’re allowed a moment.</p>${link('Take a breather ↗','#focus','text-link')}</div>`+classroomEntry()+contactSection()}
function classroomEntry(){return `<section class="classroom-entry"><div><span class="eyebrow">YOUR CLASSROOM, A LITTLE MORE CONNECTED</span><h2>Meet. Practise. Find your next step.</h2><p>Browse confirmed tutoring sessions, reviewed resources and your own account.</p></div><div class="actions">${link('Shared timetable ↗','#classroom','button small')}${link('Resource library','#library','button secondary small')}${link('My account','#account','button secondary small')}</div></section>`}
function contactSection(){return `<section class="contact-section" aria-labelledby="contact-heading"><div class="section-heading"><div><span class="eyebrow">A LITTLE SUPPORT. A SHARED PURPOSE.</span><h2 id="contact-heading">Learn with us. Make a difference.</h2><p>Free tuition for matrics, volunteer tutoring and donations.</p></div>${link('Get in touch ↗','#connect','text-link')}</div><div class="contact-grid">${contactOptions.map(o=>`<article class="contact-card"><span class="contact-icon" aria-hidden="true">${o.icon}</span><span class="eyebrow">${esc(o.label)}</span><h3>${esc(o.title)}</h3><p>${esc(o.description)}</p>${link(esc(o.button),whatsappURL(o.id),'button secondary',true)}</article>`).join('')}</div><p class="contact-number">WhatsApp <strong>${esc(contact.name)}</strong>, ${esc(contact.role)}: ${link(esc(contact.number),whatsappURL(),'contact-number-link',true)}</p></section>`}
function connectPage(){return head('A little support.<br><em>A bigger possibility.</em>','Whether you need free matric tuition, would like to volunteer as a tutor or want to donate, Godfrey is your contact at Study Zone.','LET’S CONNECT')+`<section class="contact-intro"><div class="logo-crop"><img src="assets/study-zone-logo.png" alt="StudyZone logo"></div><div><span class="eyebrow">FOUNDER OF STUDY ZONE</span><h2>${esc(contact.name)}</h2><p>${link('WhatsApp '+esc(contact.number)+' ↗',whatsappURL(),'contact-number-link',true)}</p></div></section>`+contactSection()+`<div class="notice">Each button opens WhatsApp with a message you can edit before sending. Contact Godfrey to confirm tuition availability, volunteer arrangements or donation details.</div>`}
function subjectLibrary(){return head('A subject for every<br><em>kind of bright.</em>','Explore the matric subject library, including official and additional languages. Pin your own combination and follow the topics at your pace.','THE SUBJECT UNIVERSE')+`<div class="toolbar"><input id="subject-search" type="search" placeholder="Find a subject or topic…" aria-label="Search subjects and topics"><select id="subject-order" aria-label="Sort subjects"><option value="featured">Featured first</option><option value="alpha">A to Z</option><option value="pinned">My pinned subjects</option></select></div><div class="chips" aria-label="Subject groups">${['All subjects',...new Set(subjects.map(s=>s.group))].map(x=>b(esc(x),'group',`data-group="${esc(x)}" aria-pressed="${searchGroup===x}"`,'chip'+(searchGroup===x?' active':''))).join('')}</div><p class="result-count" id="subject-count"></p><div class="subject-grid" id="subject-results"></div><div class="notice" style="margin-top:24px">Study spaces combine revision starters, topic roadmaps and official resources. Mathematics, Physical Sciences, Mathematical Literacy and Accounting include the expanded practice collections from Simoné’s subject studios. Language roadmaps are in English; use your prescribed texts and registered language level for assessment.</div>`}
function filterSubjects(){const q=($('#subject-search')?.value||'').toLowerCase().trim();const order=$('#subject-order')?.value;let list=subjects.filter(s=>(searchGroup==='All subjects'||s.group===searchGroup)&&(order!=='pinned'||state.pins.includes(s.id))&&(!q||[s.name,s.group,s.description,...s.topics.map(t=>t.title)].join(' ').toLowerCase().includes(q)));if(order==='alpha')list.sort((a,b)=>a.name.localeCompare(b.name));$('#subject-count').textContent=`${list.length} subject${list.length===1?'':'s'} · ${searchGroup.toLowerCase()}`;$('#subject-results').innerHTML=cards(list)||empty('No subjects found.','Try another spelling or choose a different subject group.')}
function subjectPage(s){if(!s)return missing();const p=progress(s);return head(esc(s.name),esc(s.description),`${esc(s.group)} · GRADE 12`,b(state.pins.includes(s.id)?'♥ Pinned to home':'♡ Pin to home','pin',`data-id="${s.id}"`,'button secondary')+link('Practise ↗',`#practice/${s.id}`,'button'))+`<div class="two-col"><section><div class="panel"><div class="section-heading" style="margin:0 0 22px"><div><h2>Your topic trail</h2><p>Learn a little. Try a little. Tick off what you’ve explored.</p></div><span class="pill green">${p}% EXPLORED</span></div>${s.pathways?`<label>My specialisation<select id="specialisation" data-subject="${s.id}">${options(s.pathways,state.profile[s.id]||s.pathways[0])}</select></label>`:''}${s.language?`<div class="notice">English study roadmap · ${esc((s.levels||['HL']).join(' / '))}. Select your registered level below. Literature and language requirements vary; follow your teacher’s prescribed texts.</div><label>My language level<select id="language-level" data-subject="${s.id}">${options(s.levels||['HL'],state.profile[s.id]||s.levels?.[0])}</select></label>`:''}${s.topics.map((t,i)=>`<div class="topic-row"><span class="topic-index">${String(i+1).padStart(2,'0')}</span><div class="topic-main"><h3><a href="#lesson/${s.id}/${t.id}">${esc(t.title)}</a></h3><p>${esc(t.summary).slice(0,185)}${t.summary.length>185?'…':''}</p><div class="actions">${link('Open lesson ↗',`#lesson/${s.id}/${t.id}`,'text-link')}${link('Try a question',`#practice/${s.id}/${t.id}`,'text-link')}</div></div><input class="topic-complete" type="checkbox" data-complete="${key(s,t)}" ${state.completed.includes(key(s,t))?'checked':''} aria-label="Mark ${esc(t.title)} explored"></div>`).join('')}</div>${s.deep?'':`<div class="panel"><span class="eyebrow">TRY IT IN CONTEXT</span><h2 style="margin-top:12px">One worked starting point.</h2>${renderWorked(s.worked)}</div>`}</section><aside><div class="panel"><div class="actions" style="margin-bottom:20px">${link('Find a tutoring session ↗','#classroom/'+s.id,'button secondary small')}${link('Reviewed resources ↗','#library/'+s.id,'button secondary small')}</div><span class="eyebrow">YOUR STUDY TOOLBOX</span><h3 style="margin-top:14px">Make it stick.</h3><p>Retrieval is where the learning happens. Close the notes and see what you remember.</p><div class="actions">${link('Flashcards ↗',`#flashcards/${s.id}`,'button secondary small')}${link('Quick check',`#quiz/${s.id}`,'button small')}</div></div><div class="panel"><span class="eyebrow">THE OFFICIAL CONNECTION</span><h3 style="margin-top:14px">Go to the source.</h3><div class="source-list">${link('DBE curriculum & subject scope ↗',SOURCES.caps,'',true)}${link('Official papers & memos ↗',SOURCES.papers,'',true)}${link('Mind the Gap study guides ↗',SOURCES.guides,'',true)}${s.specialist?link('Additional-language resources ↗',SOURCES.languages,'',true):''}</div></div>${s.deep?`<div class="panel"><h3>The original subject studio</h3><p>Explore the larger collection, specialist tools and additional resources.</p>${link('Open '+esc(s.id==='accounting'?'Ledger Legends':s.id==='maths-literacy'?'Sum Sense':s.id==='mathematics'?'Plot Twist':'Quantum Jump')+' ↗',deepLinks[s.id],'button secondary small',true)}${['mathematics','physical-sciences'].includes(s.id)?`<div style="margin-top:15px">${link('Browse video lessons ↗',`#videos/${s.id}`,'text-link')}</div>`:''}</div>`:''}<div class="panel"><h3>A note to future you.</h3><p>Save a question, a reminder or the bit you want to ask your tutor.</p>${b('Add a notebook entry ↗','note',`data-subject="${s.id}"`,'button secondary small')}</div></aside></div>`}
function renderWorked(w){if(!w)return'';return`<p class="worked-question">${esc(w.question)}</p>${w.steps.map((x,i)=>`<div class="step"><span class="step-number">${i+1}</span><div><h4>${esc(x.title)}</h4><p>${esc(x.text)}</p></div></div>`).join('')}`}
function lessonPage(s,t){if(!s||!t)return missing();visit(s,t);const lessons=(t.lessons?.length?t.lessons:[['The big idea',t.summary],['Start here',t.prerequisite||'Read the question, identify the relevant concept and write down what you know.'],['Exam approach',t.tip||'Explain each step and check your answer against the question.']]);return link('← '+esc(s.name),`#subject/${s.id}`,'back-link')+head(esc(t.title),'A little understanding before the next question.',esc(s.name),b('♡ Save lesson','bookmark',`data-subject="${s.id}" data-topic="${t.id}"`,'button secondary')+b('Print lesson','print','','button secondary'))+`<div class="two-col"><article><div class="panel"><p>${esc(t.summary)}</p>${t.formula?`<div class="formula">${esc(t.formula)}</div>`:''}${lessons.map((l,i)=>`<section class="lesson-block"><h3><span>${i+1}</span>${esc(Array.isArray(l)?l[0]:l.title)}</h3><p>${esc(Array.isArray(l)?l[1]:l.text)}</p></section>`).join('')}</div>${t.trap?`<div class="callout"><strong>That sneaky little trap.</strong><p>${esc(t.trap)}</p></div>`:''}<div class="panel"><h3>Before you move on</h3><p>${esc(t.tip||t.memory||'Close your notes and explain the idea in your own words. Compare your explanation with the lesson and identify one detail to improve.')}</p><label class="check-label"><input type="checkbox" data-complete="${key(s,t)}" ${state.completed.includes(key(s,t))?'checked':''}>I have explored this topic</label><div class="actions">${link('Try a question ↗',`#practice/${s.id}/${t.id}`,'button')}${b('Add my own note','note',`data-subject="${s.id}" data-topic="${t.id}"`,'button secondary')}</div></div></article><aside><div class="panel"><span class="eyebrow">RECALL, DON’T JUST REREAD</span><h3 style="margin-top:14px">Can you teach it back?</h3><p>Explain it to an imaginary friend. Notice where you get stuck. That is your next starting point.</p>${link('Open flashcards ↗',`#flashcards/${s.id}`,'text-link')}</div><div class="panel"><h3>Keep exploring</h3>${s.topics.filter(x=>x.id!==t.id).slice(0,5).map(x=>`<a class="saved-link" href="#lesson/${s.id}/${x.id}">${esc(x.title)} ↗</a>`).join('')}</div></aside></div>`}
function normalQuestion(s,t,i=0){if(s.id==='mathematics'||s.id==='physical-sciences'){const q=modules[s.id].example(t.id,i);return{...q,key:s.id+':'+t.id+':'+i,type:Number.isFinite(q.number)?'number':'self',value:q.number,steps:q.steps.map(x=>typeof x==='string'?{title:'Follow the working',text:x}:x)}}if(s.id==='accounting'||s.id==='maths-literacy'){const q=makeQuestion(s.id,t,i);return{...q,question:q.text,key:s.id+':'+q.key,value:q.answer,choices:q.options||q.choices,steps:q.steps.map((x,j)=>({title:['Choose the idea','Apply it','Check your answer'][Math.min(j,2)],text:x}))}}return{...s.worked,key:s.id+':starter',type:'self',steps:s.worked?.steps||[]}}
function practicePage(sid,tid,index){const s=subject(sid)||subject(practiceSubject)||subjects[0];practiceSubject=s.id;const t=topic(s,tid)||s.topics[0];const i=Math.max(0,Math.min(99,Number(index)||0));currentQuestion=normalQuestion(s,t,i);revealed=0;const q=currentQuestion;return head('A little practice.<br><em>A lot of possibility.</em>','Try first. Then unfold the working one step at a time. Mistakes are useful information.','THE PRACTICE STUDIO',link('Quick quiz ↗',`#quiz/${s.id}`,'button secondary'))+`<div class="toolbar"><select id="practice-subject" aria-label="Practice subject">${subjectOptions(s.id)}</select><select id="practice-topic" data-subject="${s.id}" aria-label="Practice topic">${options(s.topics.map(x=>({id:x.id,name:x.title})),t.id)}</select>${s.deep?b('Fresh question ↻','variant',`data-subject="${s.id}" data-topic="${t.id}" data-index="${i}"`,'button secondary'):''}</div><div class="two-col"><article class="panel"><div class="actions"><span class="pill green">${esc(s.name)}</span><span class="pill">${s.deep?'ORIGINAL PRACTICE · '+(i+1):'WORKED STARTER'}</span></div>${!s.deep?`<p class="notice" style="margin-top:18px">This subject starts with a worked example and a quick check. For full exam practice, use the official papers linked in the subject space.</p>`:''}<h2 style="margin-top:24px">${esc(s.deep?t.title:'Your starting point')}</h2><p class="worked-question">${esc(q.question)}</p>${s.id==='physical-sciences'?questionDiagram(t,q)+symbolKey(t):''}${q.known?`<p><strong>What we know:</strong> ${esc(q.known)}</p>`:''}${q.type==='number'?`<form id="answer-form"><label>Your numerical answer${q.unit?' · '+esc(q.unit):''}<div class="inline-fields"><input id="practice-answer" name="answer" inputmode="decimal" required placeholder="Give it a try…" aria-label="Your numerical answer"><button class="button" type="submit">Check my answer ↗</button></div></label></form><div id="answer-feedback" aria-live="polite"></div>`:q.type==='choice'&&q.choices?`<div id="practice-choices">${q.choices.map((c,j)=>b(esc(c),'practice-choice',`data-index="${j}"`,'quiz-choice')).join('')}</div><div id="answer-feedback" aria-live="polite"></div>`:`<label>Your explanation<textarea id="practice-response" placeholder="Write your reasoning before you reveal the worked guide…"></textarea></label>${b('Save my attempt','save-attempt','','button secondary')}<div id="answer-feedback" aria-live="polite"></div>`}<hr><div class="section-heading"><div><span class="eyebrow">THE THINKING, UNFOLDED</span><h2 style="margin-top:12px">One step at a time.</h2></div><span class="pill" id="step-count">0 / ${q.steps.length}</span></div><div class="actions no-print">${b('Show the first step','step','','button')}${b('Show all working','all-steps','','button secondary')}</div><div id="worked-steps" aria-live="polite"></div><div id="worked-answer"></div><div class="actions no-print" style="margin-top:22px">${b('♡ Save this question','save-question',`data-subject="${s.id}" data-topic="${t.id}" data-index="${i}"`,'button secondary small')}${b('Print / save PDF','print','','button secondary small')}${b('Read question aloud','speak','','button secondary small')}</div></article><aside><div class="panel"><span class="eyebrow">YOUR PENCIL SPACE</span><h3 style="margin-top:14px">Make the thinking visible.</h3><label>Working & reminders<textarea id="scratchpad" placeholder="Known values → idea → working → answer → check"></textarea></label>${b('Keep in my notebook','save-scratch',`data-subject="${s.id}" data-topic="${t.id}"`,'button secondary small')}</div><div class="panel"><h3>Need the idea first?</h3><p>${esc(t.summary)}</p>${link('Open the lesson ↗',`#lesson/${s.id}/${t.id}`,'text-link')}</div>${q.trap||t.trap?`<div class="callout"><strong>Watch that little trap.</strong><p>${esc(q.trap||t.trap)}</p></div>`:''}</aside></div>`}
function showSteps(all=false){if(!currentQuestion)return;revealed=all?currentQuestion.steps.length:Math.min(revealed+1,currentQuestion.steps.length);$('#worked-steps').innerHTML=currentQuestion.steps.slice(0,revealed).map((x,i)=>`<div class="step"><span class="step-number">${i+1}</span><div><h4>${esc(x.title)}</h4><p>${esc(x.text)}</p></div></div>`).join('');$('#step-count').textContent=`${revealed} / ${currentQuestion.steps.length}`;const btn=$('[data-action="step"]');btn.textContent=revealed===currentQuestion.steps.length?'All steps unfolded ✓':'Show the next step';btn.disabled=revealed===currentQuestion.steps.length;if(revealed===currentQuestion.steps.length&&currentQuestion.type==='number')$('#worked-answer').innerHTML=`<div class="answer-box"><small>THE ANSWER</small><strong>${esc(currentQuestion.answer??currentQuestion.value)} ${esc(currentQuestion.unit||'')}</strong></div>`}
function recordScore(q,correct){state.scores.push({key:q.key,subject:q.subject||practiceSubject,correct,date:today()});state.scores=state.scores.slice(-2000);if(!state.visits.includes(today()))state.visits.push(today());save()}
function checkNumber(raw){const q=currentQuestion;const got=parseAnswer(raw);if(!Number.isFinite(got)){toast('Enter a numerical value. You can use a decimal point, decimal comma or scientific notation.');return}const tolerance=Math.abs(q.value)>0&&Math.abs(q.value)<.01?Math.abs(q.value)*.01:.011;const correct=Math.abs(got-q.value)<=tolerance;recordScore(q,correct);$('#answer-feedback').innerHTML=`<div class="answer-feedback ${correct?'':'incorrect'}">${correct?'A little breakthrough! Your answer checks out. Compare the method as well as the number.':'Not quite yet. Check the units, the sign and the question’s starting value. Unfold a step if you need a nudge.'}</div>`}
function quizData(s){let list=s.deep?s.topics.filter(t=>t.mcq).map(t=>({...t.mcq,key:s.id+':'+t.id})):s.quiz?.q?[{...s.quiz,key:s.id+':quiz'}]:[];if(!list.length&&s.deep)list=s.topics.slice(0,6).map(t=>{const q=normalQuestion(s,t,0);const val=Number(q.value);if(!Number.isFinite(val))return null;const fmt=n=>Math.abs(n)<.001&&n!==0?n.toExponential(3):String(Math.round(n*1000)/1000);const vals=[val,val===0?1:val*2,val===0?-1:-val,val===0?2:val/2];return{q:q.question,choices:vals.map(n=>fmt(n)+(q.unit?' '+q.unit:'')),correct:0,why:q.steps.map(x=>x.text).join(' '),key:s.id+':'+t.id}}).filter(Boolean);return list}
let quizIndex=0;
function quizPage(sid){const s=subject(sid)||subject('life-sciences');const list=quizData(s);if(!list.length)return subjectPage(s);quizIndex=Math.min(quizIndex,list.length-1);choice=null;quizChecked=false;return head('A quick little check.','Choose an answer, then read the explanation. It is a checkpoint, not a judgement.','RETRIEVAL PRACTICE')+`<div class="toolbar"><select id="quiz-subject" aria-label="Quiz subject">${subjectOptions(s.id)}</select><span class="pill">${quizIndex+1} / ${list.length}</span></div><div class="panel" style="max-width:850px"><span class="eyebrow">${esc(s.name)}</span><h2 style="margin-top:20px;font-family:Georgia,serif;font-weight:400;line-height:1.4">${esc(list[quizIndex].q)}</h2><div id="quiz-choices">${list[quizIndex].choices.map((c,i)=>`<button class="quiz-choice" data-action="quiz-choice" data-index="${i}" aria-pressed="false"><span>${String.fromCharCode(65+i)}</span>${esc(c)}</button>`).join('')}</div><div id="quiz-feedback" aria-live="polite"></div><div class="actions" style="margin-top:22px">${b('Check my thinking','check-quiz',`data-subject="${s.id}"`)}${list.length>1?b('Next question ↗','next-quiz',`data-subject="${s.id}"`,'button secondary'):link('Explore the lesson ↗',`#subject/${s.id}`,'button secondary')}</div></div>`}
function checkQuiz(sid){if(choice===null){toast('Choose an answer first.');return}if(quizChecked)return;const s=subject(sid);const q=quizData(s)[quizIndex];const correct=choice===q.correct;quizChecked=true;recordScore({...q,key:q.key,subject:sid},correct);$$('[data-action="quiz-choice"]').forEach((btn,i)=>{btn.disabled=true;btn.classList.toggle('correct',i===q.correct);btn.classList.toggle('wrong',i===choice&&!correct)});$('#quiz-feedback').innerHTML=`<div class="answer-feedback ${correct?'':'incorrect'}"><strong>${correct?'You’ve got it.':'A useful learning moment.'}</strong><br>${esc(q.why)}</div>`}
function flashcardsPage(sid){const s=subject(sid)||subjects[0];const list=s.topics;flashIndex=((flashIndex%list.length)+list.length)%list.length;const t=list[flashIndex];return head('Little cards.<br><em>Big connections.</em>','Say the answer out loud before you flip the card. Come back tomorrow and try again.','THE RECALL CORNER')+`<div class="toolbar"><select id="flash-subject" aria-label="Flashcard subject">${subjectOptions(s.id)}</select><span class="pill">${flashIndex+1} / ${list.length}</span></div><button class="flashcard" data-action="flip" data-subject="${s.id}" aria-label="${flashFlipped?'Show topic':'Reveal explanation'}"><span class="eyebrow">${flashFlipped?'THE CONNECTION':'CAN YOU EXPLAIN…'}</span>${flashFlipped?`<p style="margin-top:24px">${esc(t.summary)}</p>`:`<h2 style="margin-top:24px">${esc(t.title)}</h2>`}<small>${flashFlipped?'Click to see the topic again':'Think first. Click to reveal.'}</small></button><div class="actions" style="justify-content:center">${b('← Previous','flash-prev',`data-subject="${s.id}"`,'button secondary')}${b(flashFlipped?'Show topic':'Flip card ↻','flip',`data-subject="${s.id}"`)}${b('Next →','flash-next',`data-subject="${s.id}"`,'button secondary')}</div>`}
function videosPage(sid){const s=subject(sid)||subjects[0];const list=s.id==='physical-sciences'?scienceVideos:s.id==='mathematics'?mathsVideos:[];return head('Press play.<br><em>Find your aha.</em>','Topic-organised video lessons from the original subject studios. External videos need a connection.','THE WATCH & LEARN ROOM')+`<div class="toolbar"><select id="video-subject" aria-label="Video subject">${options(subjects.filter(s=>['mathematics','physical-sciences'].includes(s.id)),s.id)}</select><select id="video-topic" aria-label="Filter videos by topic"><option value="">All topics</option>${options(s.topics.map(t=>({id:t.id,name:t.title})))}</select><input id="video-search" type="search" aria-label="Search video lessons" placeholder="Search video titles…"></div><p class="result-count" id="video-count"></p><div class="video-grid" id="video-results"></div>`}
function filterVideos(){const sid=$('#video-subject').value;const source=sid==='physical-sciences'?scienceVideos:mathsVideos;const tid=$('#video-topic').value;const query=$('#video-search').value.toLowerCase();const seen=new Set();const list=source.filter(v=>{const k=v.id+v.topic;if(seen.has(k))return false;seen.add(k);return(!tid||v.topic===tid)&&(!query||(v.title+' '+v.source).toLowerCase().includes(query))});const shown=list.slice(0,60);$('#video-count').textContent=`${list.length} matching lessons${list.length>60?' · showing the first 60; choose a topic to narrow the collection':''}`;$('#video-results').innerHTML=shown.map(v=>`<article class="video-card"><button data-action="play-video" data-video="${esc(v.id)}" data-title="${esc(v.title)}" class="video-visual" style="border:0;padding:0;width:100%" aria-label="Play ${esc(v.title)}"><img src="https://i.ytimg.com/vi/${esc(v.id)}/mqdefault.jpg" alt="" loading="lazy" referrerpolicy="no-referrer"><span class="video-play">▶</span></button><div class="video-copy"><h3>${esc(v.title)}</h3><p>${esc(v.source)}</p></div></article>`).join('')||empty('No videos found.','Try a different topic or search term.')}
const labSets={science:scienceLabs,maths:mathsLabs};
function labPage(kind='science',id){const set=labSets[kind]||scienceLabs;const selected=set.simulations.find(x=>x.id===id);if(!selected)return head('A little curious?<br><em>You’re in the right place.</em>','Move a slider. Make a prediction. See what changes. Explore the science and maths models from Quantum Jump and Plot Twist.','THE CURIOSITY LAB')+`<div class="chips">${link('Science experiments','#lab/science','chip'+(kind==='science'?' active':''))}${link('Maths playground','#lab/maths','chip'+(kind==='maths'?' active':''))}</div><div class="subject-grid">${set.simulations.map(x=>`<a href="#lab/${kind}/${x.id}" class="subject-card"><div class="subject-symbol">${kind==='science'?'⚛':'∑'}</div><h3 style="margin-top:18px">${esc(x.title)}</h3><p>${esc(x.subtitle)}</p><span class="text-link">Try the model ↗</span></a>`).join('')}</div>`;return link('← Back to the lab',`#lab/${kind}`,'back-link')+head(esc(selected.title),esc(selected.subtitle),'CHANGE SOMETHING. NOTICE SOMETHING.')+`<div class="two-col"><article class="panel"><span class="eyebrow">MAKE A PREDICTION</span><p style="margin-top:12px">${esc(selected.predict)}</p><div id="lab-output"></div><div class="notice">${esc(selected.assumption)}</div></article><aside><div class="panel"><h3>You’re in control.</h3>${[selected.a,selected.b].map((a,i)=>`<label><span class="range-head"><span>${esc(a[0])}</span><output id="lab-value-${i}">${a[4]} ${esc(a[5]||'')}</output></span><input id="lab-input-${i}" type="range" min="${a[1]}" max="${a[2]}" step="${a[3]}" value="${a[4]}" data-lab="${selected.id}" data-kind="${kind}" aria-label="${esc(a[0])}"></label>`).join('')}${b('Record an observation','note',`data-subject="${kind==='science'?'physical-sciences':'mathematics'}"`,'button secondary small')}</div><div class="panel"><h3>Predict → change → explain.</h3><p>Change one quantity at a time. Explain what happened using the relationship, not only the picture.</p></div></aside></div>`}
function updateLab(){const a=$('#lab-input-0');if(!a)return;const bb=$('#lab-input-1');const kind=a.dataset.kind;const model=labSets[kind].simulations.find(x=>x.id===a.dataset.lab);const out=labSets[kind].simulationView(model.id,Number(a.value),Number(bb.value));$('#lab-value-0').textContent=a.value+' '+(model.a[5]||'');$('#lab-value-1').textContent=bb.value+' '+(model.b[5]||'');$('#lab-output').innerHTML=`<div class="lab-svg">${out.diagram}</div><div class="lab-readout">${esc(out.readout)}</div><p>${esc(out.explanation)}</p>`}
const paperCollections=[{year:2025,name:'November 2025',url:'https://www.education.gov.za/Curriculum/NationalSeniorCertificate(NSC)Examinations/2025NovemberExamPapers.aspx'},{year:2024,name:'November 2024',url:'https://www.education.gov.za/2024NSCNovemberpastpapers.aspx'},{year:2023,name:'November 2023',url:'https://www.education.gov.za/Curriculum/NationalSeniorCertificate(NSC)Examinations/2023NSCNovemberpastpapers.aspx'}];
function papersPage(){return head('Follow the<br><em>paper trail.</em>','Official question papers, marking guidelines and selected worked questions. Try a paper, mark honestly and turn the mistakes into your next study plan.','THE EXAM REVISION ROOM',b('Print a practice sheet','worksheet','','button secondary'))+`<div class="toolbar"><select id="paper-subject" aria-label="Past-paper subject">${subjectOptions('mathematics')}</select><select id="paper-year" aria-label="Paper year"><option value="">All years</option>${options(['2026','2025','2024','2023','2022','2021','2020'])}</select><select id="paper-number" aria-label="Paper number"><option value="">All papers</option><option value="1">Paper 1</option><option value="2">Paper 2</option></select></div><div id="paper-results"></div>`}
function filterPapers(){const sid=$('#paper-subject').value;const year=$('#paper-year').value;const paper=$('#paper-number').value;const s=subject(sid);const list=(sid==='physical-sciences'?sciencePapers:sid==='mathematics'?mathsPapers:[]).filter(p=>(!year||String(p.year)===year)&&(!paper||String(p.paper)===paper));const bank=(sid==='accounting'?accountingBank:sid==='maths-literacy'?mathslitBank:[]).filter(p=>(!year||String(p.year)===year)&&(!paper||String(p.paper)===paper));$('#paper-results').innerHTML=`<div class="two-col"><section><div class="panel"><span class="eyebrow">${esc(s.name)} · OFFICIAL COLLECTIONS</span><h2 style="margin-top:14px">The original paper. The original memo.</h2><p>Choose the subject and language on the DBE collection page. Availability varies by subject and sitting.</p>${paperCollections.filter(c=>!year||String(c.year)===year).map(c=>`<div class="paper-row"><div><h3>${esc(c.name)} national papers</h3><p>DBE · subject question papers and marking guidelines</p></div>${link('Open collection ↗',c.url,'button secondary small',true)}</div>`).join('')}${link('Browse every year & sitting ↗',SOURCES.papers,'button small',true)}</div>${list.length?`<div class="panel"><h2>From the subject studio</h2><p>Additional direct paper links from ${sid==='mathematics'?'Plot Twist':'Quantum Jump'}. Source labels identify national or provincial collections and mirrors.</p>${list.map(p=>`<div class="paper-row"><div><h3>${p.year} · Paper ${p.paper} · ${esc(p.sitting||'November')}</h3><p>${esc(p.host||p.province||'DBE / subject collection')}</p></div><div class="actions">${p.question?link('Question paper ↗',p.question,'button secondary small',true):''}${p.memo?link('Memo ↗',p.memo,'button secondary small',true):''}</div></div>`).join('')}</div>`:''}${bank.length?`<div class="panel"><span class="eyebrow">EXAM FIGURES. EXPLAINED WORKING.</span><h2 style="margin-top:14px">The selected question bank</h2><p>Adapted question summaries use figures from the original exams. Follow the source links for the complete question and marking guidance.</p>${bank.map(q=>`<a class="saved-link" href="#past/${sid}/${q.id}">${esc(q.title)} ↗<small>DBE November ${q.year} · Paper ${q.paper} · Q${esc(q.ref)}</small></a>`).join('')}</div>`:''}</section><aside><div class="panel"><span class="eyebrow">A BETTER WAY TO REVISE</span><h3 style="margin-top:14px">Try → mark → notice.</h3><p>1. Work under the paper’s stated time limit.</p><p>2. Use the marking guideline after your attempt.</p><p>3. Record why marks were lost: concept, method, reading or calculation.</p><p>4. Practise that skill again on another day.</p>${link('Plan a paper session ↗','#planner','button secondary small')}</div><div class="panel"><h3>Start a focused session.</h3><p>Use the timer to settle into one section at a time.</p>${link('Open the focus room ↗','#focus','text-link')}</div><div class="panel"><h3>The full subject scope</h3><p>Check the official curriculum and your teacher’s prescribed work before deciding what to leave out.</p>${link('DBE CAPS ↗',SOURCES.caps,'text-link',true)}</div></aside></div>`}
function pastQuestionPage(sid,id){const s=subject(sid);const q=(sid==='accounting'?accountingBank:mathslitBank).find(q=>q.id===id);if(!s||!q)return missing();practiceSubject=sid;currentQuestion={question:q.prompt,value:q.value??q.answer,answer:q.value??q.answer,unit:q.unit,key:sid+':past:'+q.id,type:Number.isFinite(q.value)?'number':'self',steps:q.steps.map((t,i)=>({title:i===0?'Find your start':'Follow the working',text:t}))};revealed=0;return link('← Back to the paper trail','#papers','back-link')+head(esc(q.title),`DBE November ${q.year} · ${esc(s.name)} · Paper ${q.paper} · Question ${esc(q.ref)}`,'SELECTED PAST-PAPER QUESTION',b('Print / save PDF','print','','button secondary'))+`<div class="panel"><div class="notice">Adapted question summary using exam figures. Check the complete original question and marking guideline for context and method marks.</div><p class="worked-question">${esc(q.prompt)}</p>${currentQuestion.type==='number'?`<form id="answer-form"><label>Your numerical answer · ${esc(q.unit||'')}<input name="answer" id="practice-answer" placeholder="Try the calculation first…" inputmode="decimal" required></label><button class="button" type="submit">Check my answer ↗</button></form>`:`<label>Your response<textarea id="practice-response" placeholder="Explain your reasoning…"></textarea></label>`}<div id="answer-feedback" aria-live="polite"></div><hr><div class="section-heading"><h2>The working, unfolded.</h2><span class="pill" id="step-count">0 / ${q.steps.length}</span></div><div class="actions no-print">${b('Show the first step','step')}${b('Show all working','all-steps','','button secondary')}</div><div id="worked-steps" aria-live="polite"></div><div id="worked-answer"></div><hr><div class="actions">${q.source?.memo?link('Original marking guideline ↗',q.source.memo,'button secondary small',true):''}${q.source?.collection?link('Original paper collection ↗',q.source.collection,'button secondary small',true):''}</div>${q.memoPage?`<p style="font-size:11px;margin-top:14px">Source memo page ${q.memoPage}. Original DBE material retains its source credit.</p>`:''}</div>`}
function worksheet(){const s=subject($('#paper-subject')?.value||practiceSubject)||subjects[0];const qs=s.deep?s.topics.slice(0,6).map((t,i)=>normalQuestion(s,t,i+3)):[{...s.worked},...(s.quiz?[{question:s.quiz.q+' '+s.quiz.choices.map((c,i)=>String.fromCharCode(65+i)+'. '+c).join('  '),steps:[{title:'Answer',text:s.quiz.choices[s.quiz.correct]+'. '+s.quiz.why}]}]:[])];modal(`<span class="eyebrow">PRINTABLE PRACTICE · ${esc(s.name)}</span><h2>A little room to think.</h2><p>Original practice · Compiled by Simoné Govender · BEd</p>${b('Print / save PDF','print-sheet','','button')}<div id="worksheet-content"><p>Name: ___________________ &nbsp; Date: _______________</p>${qs.map((q,i)=>`<section class="panel"><h3>${i+1}. ${esc(q.question)}</h3><p style="min-height:100px">Working:</p></section>`).join('')}<section class="print-memo"><h2>Worked guide</h2>${qs.map((q,i)=>`<div class="panel"><h3>Question ${i+1}</h3>${(q.steps||[]).map(x=>`<p>${esc(x.text||x)}</p>`).join('')}</div>`).join('')}</section></div>`)}
function plannerPage(){const weekStart=new Date(today()+'T12:00:00');weekStart.setDate(weekStart.getDate()-((weekStart.getDay()+6)%7));const days=Array.from({length:7},(_,i)=>{const d=new Date(weekStart);d.setDate(d.getDate()+i);return d.toLocaleDateString('en-CA')});const upcoming=state.sessions.filter(x=>x.date>=today()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return head('A plan with<br><em>room to breathe.</em>','Small sessions, sensible breaks and a little direction. Add your own study blocks, exam dates or confirmed tutoring links.','YOUR STUDY PLAN',b('+ Add a session','session')+b('Print plan','print','','button secondary'))+`<div class="notice">This is your personal timetable. Only add tutoring sessions and meeting links that have been confirmed by your tutor. No sessions are booked automatically.</div><div class="section-heading"><h2>This week, a little clearer.</h2><span class="pill">${dateLabel(days[0])} — ${dateLabel(days[6])}</span></div><div class="week-grid">${days.map(d=>`<div class="day-column"><h3>${new Date(d+'T12:00:00').toLocaleDateString('en-ZA',{weekday:'short'})}<small style="display:block;color:var(--muted)">${dateLabel(d)}</small></h3>${state.sessions.filter(x=>x.date===d).sort((a,b)=>a.time.localeCompare(b.time)).map(sessionCard).join('')}</div>`).join('')}</div><div class="two-col"><section class="panel"><div class="section-heading" style="margin-top:0"><h2>Coming up</h2>${b('Export calendar ↗','calendar','','text-link')}</div>${upcoming.length?upcoming.map(sessionRow).join(''):empty('A blank page is a good beginning.','Add one realistic session. Twenty-five focused minutes is a perfectly good place to start.',b('Plan a little session','session'))}</section><aside><div class="panel"><span class="eyebrow">YOUR NEXT LITTLE STEP</span><h3 style="margin-top:14px">Let your practice guide you.</h3>${nextStep()}<div style="margin-top:16px">${b('Plan that session ↗','session','','button secondary small')}</div></div><div class="panel"><h3>Keep a copy.</h3><p>Your plan stays on this device. Export a backup to move it between devices or share your own resource pack.</p><div class="actions">${b('Export backup','export','','button secondary small')}${b('Import backup','import','','button secondary small')}</div></div></aside></div>`}
function nextStep(){const missed=state.scores.filter(x=>!x.correct).at(-1);const s=subject(missed?.subject);return s?`<p>Your recent practice suggests another look at <strong>${esc(s.name)}</strong>. Revisit the method before moving to a fresh question.</p>${link('Back to '+esc(s.name)+' ↗',`#practice/${s.id}`,'text-link')}`:'<p>Choose the subject you have been avoiding. Start with one lesson and one question. Then take a proper break.</p>'+link('Pick a starting point ↗','#subjects','text-link')}
function sessionCard(x){return`<div class="session ${x.done?'done':''}"><span>${esc(x.time)} · ${Number(x.duration)||25} min</span><strong>${esc(x.title)}</strong><small>${esc(subject(x.subject)?.name||'Personal study')}</small>${x.url&&safeURL(x.url)?link('Open session ↗',safeURL(x.url),'',true):''}</div>`}
function sessionRow(x){return`<div class="paper-row"><div><h3>${x.done?'✓ ':''}${esc(x.title)}</h3><p>${dateLabel(x.date)} · ${esc(x.time)} SAST · ${Number(x.duration)||25} min · ${esc(subject(x.subject)?.name||'Personal study')}</p></div><div class="actions">${x.url&&safeURL(x.url)?link('Join ↗',safeURL(x.url),'button secondary small',true):''}${b(x.done?'Undo':'Done ✓','session-done',`data-id="${x.id}"`,'button secondary small')}${b('Remove','session-remove',`data-id="${x.id}"`,'text-link')}</div></div>`}
function sessionModal(){modal(`<span class="eyebrow">SMALL STEPS. ON PURPOSE.</span><h2>Make time for a little progress.</h2><form id="session-form"><label>What are you working on?<input name="title" required maxlength="100" placeholder="Momentum practice / confirmed tutoring session"></label><label>Subject<select name="subject">${subjectOptions(practiceSubject)}</select></label><div class="inline-fields"><label>Date<input name="date" type="date" value="${today()}" required></label><label>Time · South Africa<input name="time" type="time" value="16:00" required></label></div><div class="inline-fields"><label>Minutes<input type="number" name="duration" min="5" max="300" value="25" required></label><label>Confirmed meeting link · optional<input name="url" type="url" placeholder="https://meet.google.com/…"></label></div><button class="button" type="submit">Add to my plan ↗</button></form>`)}
function exportCalendar(){const escapeICS=s=>String(s).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const stamp=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const list=state.sessions.filter(x=>!x.done);if(!list.length){toast('Add a session before exporting your calendar.');return}const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Study Zone//Personal study plan//EN','CALSCALE:GREGORIAN',...list.flatMap(x=>{const d=new Date(`${x.date}T${x.time}:00+02:00`);return['BEGIN:VEVENT','UID:'+x.id+'@studyzone','DTSTAMP:'+stamp(new Date()),'DTSTART:'+stamp(d),'DTEND:'+stamp(new Date(d.getTime()+(Number(x.duration)||25)*60000)),'SUMMARY:'+escapeICS(x.title),'DESCRIPTION:'+escapeICS(subject(x.subject)?.name||'Personal study'),...(x.url&&safeURL(x.url)?['URL:'+safeURL(x.url)]:[]),'END:VEVENT']}),'END:VCALENDAR'];download('Study_Zone_Plan.ics',lines.join('\r\n'),'text/calendar');toast('Calendar exported. Import it into your calendar app.')}
function notebookPage(){return head('A home for<br><em>your little aha’s.</em>','Your notes, saved lessons and questions worth coming back to. A messy thought can be the beginning of a good idea.','YOUR NOTEBOOK',b('+ Add a note','note')+b('Export backup','export','','button secondary'))+`<div class="two-col"><section>${state.notes.length?state.notes.slice().reverse().map(n=>`<article class="panel note-card"><span class="eyebrow">${esc(subject(n.subject)?.name||'MY LITTLE NOTES')}</span><h3 style="margin-top:12px">${esc(n.title)}</h3><pre>${esc(n.body)}</pre><div class="actions"><small>${esc(n.date)}</small>${b('Edit','edit-note',`data-id="${n.id}"`,'text-link')}${b('Remove','remove-note',`data-id="${n.id}"`,'text-link')}</div></article>`).join(''):empty('Catch a thought. Keep a breakthrough.','Add your first note, or save a piece of working from the practice studio.',b('Write a little note','note'))}</section><aside><div class="panel"><h2>Saved for later.</h2>${state.saved.length?state.saved.map(x=>`<div class="paper-row"><a href="${esc(x.url)}"><h3>${esc(x.title)}</h3><p>${esc(subject(x.subject)?.name||'Study Zone')}</p></a>${b('×','unsave',`data-id="${esc(x.id)}" aria-label="Remove saved item"`,'icon-button')}</div>`).join(''):'<p>Tap “Save lesson” or “Save this question” while exploring to keep it here.</p>'}</div><div class="panel"><h3>Your work belongs with you.</h3><p>Notes and progress are saved in this browser. Keep a backup before clearing browser data or switching devices.</p><div class="actions">${b('Export','export','','button secondary small')}${b('Import','import','','button secondary small')}</div></div></aside></div>`}
function noteModal(sid='',tid='',id=''){const n=state.notes.find(x=>x.id===id);modal(`<span class="eyebrow">KEEP A LITTLE THINKING</span><h2>${n?'A little refinement.':'Catch that thought.'}</h2><form id="note-form" data-id="${esc(id)}"><label>A title<input name="title" maxlength="120" value="${esc(n?.title||'')}" placeholder="The bit I finally understood…" required></label><label>Subject<select name="subject"><option value="">Personal note</option>${subjectOptions(n?.subject||sid)}</select></label><label>Your note<textarea name="body" maxlength="20000" required placeholder="Questions, reminders, working, tiny victories…">${esc(n?.body||'')}</textarea></label><button class="button" type="submit">Keep this thought ↗</button></form>`)}
function focusPage(){return head('You don’t have to<br><em>do it all at once.</em>','A quieter corner for a little focus, a proper break and a fresh start.','A LITTLE BREATHING ROOM',b('Quiet view','quiet','','button secondary'))+`<div class="two-col"><section class="panel center"><span class="eyebrow" id="timer-kind">${timer.kind.toUpperCase()} SESSION</span><div class="timer" id="timer-display">${clock(timer.remaining)}</div><p>One task. A little time. You’ve got a starting point.</p><div class="chips" style="justify-content:center">${[15,25,45].map(m=>b(m+' min','timer-preset',`data-minutes="${m}"`,'chip')).join('')}${b('5 min break','timer-break','','chip')}</div><div class="actions">${b(timer.run?'Pause':'Start a little focus ↗','timer-toggle','id="timer-toggle"')}${b('Reset','timer-reset','','button secondary')}</div><hr><label style="text-align:left">My one thing for this session<input id="focus-task" maxlength="120" placeholder="Just five questions. Just one section." value="${esc(state.profile.focusTask||'')}"></label></section><aside><div class="panel center"><span class="eyebrow">A MOMENT TO SETTLE</span><div class="breathe-orb" id="breathe-orb">Take a moment</div><p id="breathe-caption">Let your breathing find a comfortable pace. You can stop whenever you want.</p>${b('Start the gentle guide','breathe','','button secondary small')}</div><div class="panel"><h3>When the brain says “everything”.</h3><p>Write down one next action. Make it smaller if you need to. A glass of water, a stretch or asking your tutor one clear question can be a good next step.</p>${link('Open Mind Weather ↗','https://mymindweather.study/','text-link',true)}</div></aside></div>`}
function clock(n){return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function updateTimer(){if(timer.run){timer.remaining=Math.max(0,Math.ceil((timer.end-Date.now())/1000));if(timer.remaining===0){timer.run=false;if(timer.kind==='Focus'&&!timer.credited){state.focusMinutes+=Math.round(timer.total/60);timer.credited=true;if(!state.visits.includes(today()))state.visits.push(today());save()}toast(timer.kind==='Focus'?'A little focus, complete. Take a well-earned break.':'Break complete. Choose one small next step.')}}if($('#timer-display'))$('#timer-display').textContent=clock(timer.remaining);if($('#timer-toggle'))$('#timer-toggle').textContent=timer.run?'Pause':timer.remaining===0?'Start again ↗':'Start a little focus ↗';$('#timer-dock').hidden=!timer.run||route[0]==='focus';if(!$('#timer-dock').hidden)$('#timer-dock').innerHTML=`<a href="#focus">◷ ${clock(timer.remaining)} · ${timer.kind}</a>${b('Ⅱ','timer-toggle','aria-label="Pause timer"','')}`}
function tutorPage(){return head('Good lessons start<br><em>with a little preparation.</em>','A practical desk for building a resource pack, planning sessions and keeping teaching notes in one place.','THE TUTOR DESK',b('+ Add a resource','resource')+b('Export resource pack','export-pack','','button secondary'))+`<div class="classroom-entry compact"><div><strong>Ready to work with your class?</strong><p>Approved tutors can publish confirmed sessions, submit resources and manage class registers.</p></div>${link('Open programme desk ↗','#staff','button small')}</div><div class="tutor-invite"><div><strong>Want to volunteer to tutor matrics?</strong><p>Contact Godfrey to discuss your subjects, availability and the next steps.</p></div>${link('Volunteer on WhatsApp ↗',whatsappURL('volunteer'),'button secondary small',true)}</div><div class="notice">This desk is a personal workspace. Saved resources and sessions stay on this device. Export a resource pack to share it; learners can import the pack here. Adding a resource does not publish it to everyone.</div><div class="two-col"><section><div class="panel"><h2>Your resource pack</h2>${state.resources.length?state.resources.map(r=>`<div class="paper-row"><div><h3>${esc(r.title)}</h3><p>${esc(subject(r.subject)?.name||'All subjects')} · ${esc(r.type||'Resource')}</p>${r.description?`<p>${esc(r.description)}</p>`:''}</div><div class="actions">${safeURL(r.url)?link('Open ↗',safeURL(r.url),'button secondary small',true):''}${b('Remove','remove-resource',`data-id="${r.id}"`,'text-link')}</div></div>`).join(''):empty('A little collection with a lot of potential.','Add lesson links, revision documents or confirmed classroom resources.',b('Add the first resource','resource'))}</div><div class="panel"><h2>A lesson that leaves room to learn.</h2><div class="lesson-block"><h3><span>1</span>Start with a check-in</h3><p>Ask one focused question to identify prior understanding. Make the learning goal visible.</p></div><div class="lesson-block"><h3><span>2</span>Model the thinking</h3><p>Use a worked example. Reveal one step at a time and explain why that step belongs.</p></div><div class="lesson-block"><h3><span>3</span>Let learners try</h3><p>Change the numbers or context. Allow thinking time, then compare methods and address the error.</p></div><div class="lesson-block"><h3><span>4</span>Leave a useful next step</h3><p>Set a small practice task, specify the resource and explain how learners can check their work.</p></div><div class="actions no-print">${link('Open practice studio ↗','#practice','button')}${b('Print this checklist','print','','button secondary')}</div></div></section><aside><div class="panel"><h3>A confirmed session.</h3><p>Add an agreed time and meeting link to your personal plan, then export the calendar if needed.</p>${b('Add to my plan ↗','session','','button secondary small')}</div><div class="panel"><h3>Bring a resource pack in.</h3><p>Import a Study Zone resource pack shared by your tutor. Review external links before using them.</p>${b('Import a pack','import-pack','','button secondary small')}</div><div class="panel"><h3>Use official material.</h3><div class="source-list">${link('DBE subject curriculum ↗',SOURCES.caps,'',true)}${link('DBE papers & marking guides ↗',SOURCES.papers,'',true)}${link('DBE study guides ↗',SOURCES.guides,'',true)}</div></div></aside></div>`}
function resourceModal(){modal(`<span class="eyebrow">BUILD A USEFUL LITTLE COLLECTION</span><h2>A resource worth keeping.</h2><form id="resource-form"><label>Title<input name="title" required maxlength="140" placeholder="Organic chemistry revision notes"></label><label>Subject<select name="subject"><option value="">All subjects</option>${subjectOptions('')}</select></label><div class="inline-fields"><label>Resource type<select name="type">${options(['Notes','Video','Worksheet','Presentation','Classroom','Other'])}</select></label><label>Resource link<input name="url" type="url" required placeholder="https://…"></label></div><label>A little context<textarea name="description" maxlength="600" placeholder="What learners should use this for…"></textarea></label><button class="button" type="submit">Add to my resource pack ↗</button></form>`)}
function aboutPage(){return head('A little support.<br><em>A world of possibility.</em>','A space for learners to ask, practise, get it wrong and try again. The next chapter is worth showing up for.','THIS IS STUDY ZONE')+`<div class="two-col"><section><div class="panel"><span class="eyebrow">THE PEOPLE BEHIND THE PURPOSE</span><h2 style="margin-top:14px">Built around the learner.</h2><h3>Godfrey · Founder of Study Zone</h3><p>Study Zone’s founder, Godfrey, is recognised here for the initiative and its focus on connecting learners with learning support.</p><p class="founder-contact">For free matric tuition, volunteer tutoring or donations, ${link('contact Godfrey on WhatsApp ↗',whatsappURL(),'text-link',true)} at <strong>${esc(contact.number)}</strong>.</p><h3>Simoné Govender · Platform design & development</h3><p>Simoné brings a Bachelor of Education, Mathematics and Physical Sciences teaching experience, web development and UX/UI design to this learning hub. Her subject studios bring together structured explanations, practice and tools for independent learning.</p><p>The hub builds on her tutoring experience through Study Zone and Umuzi. Mind Weather is credited as an Umuzi team project.</p><div class="actions">${link('Explore Simoné’s portfolio ↗','https://cosmicbubblegumgirl.github.io/simone-cosmic-portfolio/','button secondary small',true)}${link('LinkedIn ↗','https://www.linkedin.com/in/simone-govender-dev/','button secondary small',true)}</div></div><div class="panel"><h2>Your learning, with a little context.</h2><p>The subject universe covers the main NSC subject families, official languages, South African Sign Language and approved additional languages. Civil, Electrical and Mechanical Technology include their specialisation pathways.</p><p>Content depth varies: the four expanded subject studios contain larger practice collections; other spaces begin with topic roadmaps, a worked starter, recall tools and links to official material. Language roadmaps are in English and do not replace teaching or prescribed texts in your registered language.</p><p>Original practice is labelled separately from adapted past-paper summaries. Use the complete official paper and marking guideline for exam context and method marks. Your school’s prescribed work, language level and assessment requirements remain the guide for your course.</p><p>Study Zone is an independent learning hub. Links to DBE, IEB and other services identify resources; they do not imply endorsement. Subject catalogues and source links were checked in October 2026.</p></div><div class="panel"><h2>A small, clear privacy promise.</h2><p>You can use the included study tools without an account. Your nickname, notes, personal timetable and practice progress stay in this browser unless you choose to save a private online copy. Signing in does not upload existing device notes automatically. Clearing browser data can remove local work, so keep a backup.</p><p>The shared classroom uses an account for session registration, attendance, tutor requests and feedback. Registered learner names and attendance are visible to programme staff and the session’s tutor. A subject progress summary is visible only when you opt in for that session; private notes and online study copies are not visible to tutors.</p><p>Shared resources are reviewed before public publication. Tutor submissions and uploaded files can be inspected by programme administrators. Public resource packs include only the resources you choose to export. Backups include your personal study data, so share them carefully. External links and embedded videos follow the providers’ own privacy practices. Video thumbnails may contact YouTube’s image service when you open the video library.</p><p>Offline mode stores this app and its included study content after a successful first visit. The shared classroom, account actions, external videos, original studio links and online papers require a connection.</p><div class="actions">${b('Export my backup','export','','button secondary small')}${b('Reading settings','settings','','button secondary small')}${b('Clear my study data','clear-data','','text-link')}</div></div></section><aside><div class="panel center"><div class="logo-crop about-logo"><img src="assets/study-zone-logo.png" alt="StudyZone original logo"></div><h3>Founded by Godfrey.</h3><p>A little more possible, together.</p></div><div class="panel"><h3>Go to the source.</h3><div class="source-list">${link('DBE FET subject curriculum ↗',SOURCES.caps,'',true)}${link('DBE past papers ↗',SOURCES.papers,'',true)}${link('DBE Mind the Gap ↗',SOURCES.guides,'',true)}${link('Additional-language resources ↗',SOURCES.languages,'',true)}${link('IEB NSC information ↗',SOURCES.ieb,'',true)}</div></div></aside></div><div class="section-heading"><h2>The little studios that came together.</h2></div><div class="three-col">${collections.map(c=>`<article class="panel collection-card"><span class="subject-symbol">${c.icon}</span><div><span class="eyebrow">${esc(c.subject)}</span><h3>${esc(c.name)}</h3><p>${esc(c.text)}</p>${link('Explore ↗',c.url,'text-link',true)}</div></article>`).join('')}</div>`}
function settingsModal(){modal(`<span class="eyebrow">MAKE YOURSELF COMFORTABLE</span><h2>Your space.<br>Your way.</h2><p>Set up a reading experience that feels comfortable for you.</p>${[['large','A little larger','Larger body text for easier reading.'],['contrast','A little clearer','Stronger text and border contrast.'],['motion','A little calmer','Reduce movement and transitions.']].map(([k,title,text])=>`<div class="settings-row"><div><strong>${title}</strong><p>${text}</p></div><input type="checkbox" data-setting="${k}" ${state.settings[k]?'checked':''} aria-label="${title}"></div>`).join('')}<div class="settings-row"><div><strong>Light / dark</strong><p>Switch the room’s colours.</p></div>${b(state.settings.theme==='dark'?'Light mode':'Dark mode','theme','','button secondary small')}</div><div class="settings-row"><div><strong>Keep your work</strong><p>Export your notes, plan and progress.</p></div>${b('Export backup','export','','button secondary small')}</div>`)}
function searchModal(){modal(`<span class="eyebrow">FIND YOUR NEXT STARTING POINT</span><h2>A little help finding it.</h2><input id="global-search" type="search" placeholder="Search subjects, topics or tools…" aria-label="Search the entire hub"><div class="search-results" id="global-results"></div>`);globalSearch('')}
function globalSearch(query){const q=query.toLowerCase().trim();const tools=[{name:'Shared tutoring timetable',url:'#classroom',detail:'Confirmed sessions and registration'},{name:'Reviewed resource library',url:'#library',detail:'Shared notes, worksheets and presentations'},{name:'My account',url:'#account',detail:'Sign in, progress copies and feedback'},{name:'Programme desk',url:'#staff',detail:'Tutor publishing, class registers and review'},{name:'Free matric tuition, volunteer tutoring and donations',url:'#connect',detail:'WhatsApp Godfrey at +27 67 122 8990'},{name:'Practice studio',url:'#practice',detail:'Questions and worked answers'},{name:'Paper trail',url:'#papers',detail:'Past papers and marking guidelines'},{name:'Curiosity lab',url:'#lab',detail:'Interactive maths and science models'},{name:'Study plan',url:'#planner',detail:'Your timetable and calendar'},{name:'Notebook',url:'#notebook',detail:'Notes and saved questions'},{name:'Focus room',url:'#focus',detail:'Pomodoro timer and a gentle pause'},{name:'Tutor desk',url:'#tutor',detail:'Build and share a resource pack'}];const all=[...subjects.map(s=>({name:s.name,url:'#subject/'+s.id,detail:s.group})),...subjects.flatMap(s=>s.topics.map(t=>({name:t.title,url:`#lesson/${s.id}/${t.id}`,detail:s.name}))),...tools];const matches=all.filter(x=>!q||(x.name+' '+x.detail).toLowerCase().includes(q)).slice(0,25);$('#global-results').innerHTML=matches.map(x=>`<a href="${x.url}" data-action="search-result"><span>↗</span><div>${esc(x.name)}<small>${esc(x.detail)}</small></div></a>`).join('')||'<p>No matches yet. Try a subject name or a shorter phrase.</p>'}
function missing(){return head('A little detour.','That page is not in this study space. Let’s find you a useful starting point.','PAGE NOT FOUND',link('Back to home','#home','button'))}
function render(keepScroll=false){route=location.hash.slice(1).split('/').map(x=>{try{return decodeURIComponent(x)}catch{return''}});if(!route[0])route=['home'];document.body.classList.remove('menu-open');$('.mobile-menu').setAttribute('aria-expanded','false');const [page,a,c,d]=route;let html='';switch(page){case'home':html=dashboard();break;case'subjects':html=subjectLibrary();break;case'subject':html=subjectPage(subject(a));break;case'lesson':html=lessonPage(subject(a),topic(subject(a),c));break;case'practice':html=practicePage(a,c,d);break;case'quiz':html=quizPage(a);break;case'flashcards':html=flashcardsPage(a);break;case'videos':html=videosPage(a);break;case'papers':html=papersPage();break;case'past':html=pastQuestionPage(a,c);break;case'lab':html=labPage(a,c);break;case'planner':html=plannerPage();break;case'notebook':html=notebookPage();break;case'focus':html=focusPage();break;case'tutor':html=tutorPage();break;case'connect':html=connectPage();break;case'classroom':case'library':case'account':case'staff':case'session':html=classroom.page(page,a);break;case'about':html=aboutPage();break;default:html=missing()}
main.innerHTML=html;document.title=(subject(a)?.name||({home:'Your next little breakthrough',subjects:'Subject universe',practice:'Practice studio',papers:'The paper trail',lab:'Curiosity lab',planner:'My study plan',notebook:'My notebook',focus:'A little breathing room',tutor:'Tutor desk',connect:'Free tuition, volunteer & donate',classroom:'Shared timetable',library:'Reviewed resources',account:'My account',staff:'Programme desk',session:'Tutoring session',about:'About Study Zone'}[page]||'Your learning space'))+' · Study Zone';$$('nav a').forEach(x=>{const active=x.dataset.nav===page||(x.dataset.nav==='subjects'&&['subject','lesson','videos','flashcards','quiz'].includes(page))||(x.dataset.nav==='classroom'&&page==='session');x.classList.toggle('active',active);if(active)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current')});if(page==='subjects')filterSubjects();if(page==='videos')filterVideos();if(page==='papers')filterPapers();if(page==='lab')updateLab();applySettings();classroom.mount();updateTimer();if(!keepScroll){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true})}}
function exportBackup(){download('Study_Zone_My_Backup.json',JSON.stringify({app:'Study Zone',exported:new Date().toISOString(),data:state},null,2));toast('Your backup is ready. Keep it somewhere safe.')}
function importFile(pack=false){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const file=input.files[0];if(!file)return;if(file.size>3000000){toast('Choose a Study Zone JSON file smaller than 3 MB.');return}let data;try{data=JSON.parse(await file.text())}catch{toast('That file could not be read. Choose a valid Study Zone JSON export.');return}if(pack){if(data.app!=='Study Zone resources'||!Array.isArray(data.resources)){toast('Choose an exported Study Zone resource pack.');return}const clean=data.resources.filter(x=>typeof x.title==='string'&&x.title.length<=140&&safeURL(x.url)&&(!x.subject||subject(x.subject))).map(x=>({id:uid(),title:x.title,url:safeURL(x.url),subject:x.subject||'',description:String(x.description||'').slice(0,600),type:String(x.type||'Resource').slice(0,40)})).slice(0,300);state.resources.push(...clean);save();render(true);toast(clean.length+' resources added to your personal desk.');return}if(data.app!=='Study Zone'||data.data?.version!==1){toast('Choose a backup exported from Study Zone.');return}const incoming=data.data;const allowed=['pins','completed','saved','notes','sessions','scores','resources','visits'];if(allowed.some(k=>!Array.isArray(incoming[k]))||!incoming.profile||typeof incoming.profile.name!=='string'){toast('That backup is missing required study data.');return}modal(`<span class="eyebrow">BRING YOUR STUDY SPACE BACK</span><h2>Restore this backup?</h2><p>This replaces the notes, progress and plan currently on this device. Export your current work first if you want to keep both copies.</p><div class="actions">${b('Export current work','export','','button secondary')}${b('Restore backup','confirm-import')}</div>`);const confirm=$('[data-action="confirm-import"]');confirm.addEventListener('click',()=>{state={...defaults(),...incoming,settings:{...defaults().settings,...incoming.settings}};state.profile.name=String(state.profile.name).slice(0,40);state.pins=state.pins.filter(x=>subject(x));state.resources=state.resources.filter(x=>safeURL(x.url));state.focusMinutes=Math.max(0,Number(state.focusMinutes)||0);save();close();render();toast('Your study space has been restored.')},{once:true})};input.click()}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;switch(a){case'menu':document.body.classList.toggle('menu-open');$('.mobile-menu').setAttribute('aria-expanded',String(document.body.classList.contains('menu-open')));syncMenu();break;case'close':close();break;case'profile':profileModal();break;case'theme':state.settings.theme=state.settings.theme==='dark'?'light':'dark';save();applySettings();if($('#dialog').open&&$('[data-setting]'))settingsModal();break;case'settings':settingsModal();break;case'search':searchModal();break;case'search-result':close();if(el.hash===location.hash)render();break;case'pin':{const id=el.dataset.id;if(!subject(id))return;const at=state.pins.indexOf(id);if(at>=0)state.pins.splice(at,1);else state.pins.push(id);save();if(route[0]==='subjects'){filterSubjects()}else render(true);toast(at>=0?'Subject unpinned.':'A new little corner of your universe. Subject pinned.');break}case'group':searchGroup=el.dataset.group;$$('[data-action="group"]').forEach(x=>{const selected=x.dataset.group===searchGroup;x.classList.toggle('active',selected);x.setAttribute('aria-pressed',String(selected))});filterSubjects();break;case'bookmark':{const s=subject(el.dataset.subject),t=topic(s,el.dataset.topic);if(!t)return;const id='lesson:'+key(s,t);if(state.saved.some(x=>x.id===id)){toast('Already tucked into your notebook.');return}state.saved.push({id,subject:s.id,title:t.title,url:`#lesson/${s.id}/${t.id}`});save();toast('Lesson tucked into your notebook.');break}case'save-question':{const s=subject(el.dataset.subject),t=topic(s,el.dataset.topic);const id='question:'+s.id+':'+t.id+':'+el.dataset.index;if(!state.saved.some(x=>x.id===id))state.saved.push({id,subject:s.id,title:t.title+' · practice '+(Number(el.dataset.index)+1),url:`#practice/${s.id}/${t.id}/${el.dataset.index}`});save();toast('Question saved for another little try.');break}case'unsave':state.saved=state.saved.filter(x=>x.id!==el.dataset.id);save();render(true);break;case'note':noteModal(el.dataset.subject,el.dataset.topic);break;case'edit-note':noteModal('','',el.dataset.id);break;case'remove-note':state.notes=state.notes.filter(x=>x.id!==el.dataset.id);save();render(true);toast('Note removed.');break;case'save-scratch':{const text=$('#scratchpad').value.trim();if(!text){toast('Add a little working first.');return}state.notes.push({id:uid(),title:topic(subject(el.dataset.subject),el.dataset.topic)?.title+' · my working',subject:el.dataset.subject,body:text,date:today()});save();toast('Your working is in the notebook.');break}case'save-attempt':{const text=$('#practice-response').value.trim();if(!text){toast('Write your explanation first.');return}state.notes.push({id:uid(),title:subject(practiceSubject).name+' · my practice attempt',subject:practiceSubject,body:currentQuestion.question+'\n\n'+text,date:today()});save();toast('Attempt saved. Compare it with the worked guide.');break}case'variant':location.hash=`practice/${el.dataset.subject}/${el.dataset.topic}/${(Number(el.dataset.index)+1)%100}`;break;case'step':showSteps();break;case'all-steps':showSteps(true);break;case'practice-choice':{if(!currentQuestion)return;const correct=Number(el.dataset.index)===currentQuestion.value;recordScore(currentQuestion,correct);$('#answer-feedback').innerHTML=`<div class="answer-feedback ${correct?'':'incorrect'}">${correct?'You’ve got the idea. Compare the working as well.':'Not quite yet. Try unfolding the first step.'}</div>`;break}case'quiz-choice':if(!quizChecked){choice=Number(el.dataset.index);$$('[data-action="quiz-choice"]').forEach((x,i)=>{x.classList.toggle('selected',i===choice);x.setAttribute('aria-pressed',String(i===choice))})}break;case'check-quiz':checkQuiz(el.dataset.subject);break;case'next-quiz':quizIndex=(quizIndex+1)%quizData(subject(el.dataset.subject)).length;render(true);break;case'flip':flashFlipped=!flashFlipped;render(true);break;case'flash-prev':flashIndex--;flashFlipped=false;render(true);break;case'flash-next':flashIndex++;flashFlipped=false;render(true);break;case'play-video':{const id=el.dataset.video;if(!/^[A-Za-z0-9_-]{11}$/.test(id))return;modal(`<span class="eyebrow">WATCH & LEARN</span><h2 style="font-size:24px">${esc(el.dataset.title)}</h2><iframe class="video-frame" src="https://www.youtube-nocookie.com/embed/${id}" title="${esc(el.dataset.title)}" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe><p style="margin-top:16px">If the provider does not permit embedding, open the lesson on YouTube.</p>${link('Open on YouTube ↗','https://www.youtube.com/watch?v='+id,'button secondary small',true)}`);break}case'speak':if('speechSynthesis' in window&&currentQuestion){speechSynthesis.cancel();const spoken=new SpeechSynthesisUtterance(currentQuestion.question);spoken.lang='en-ZA';spoken.rate=.85;speechSynthesis.speak(spoken)}else toast('Read-aloud is not available in this browser.');break;case'print':window.print();break;case'worksheet':worksheet();break;case'print-sheet':{const old=main.innerHTML;main.innerHTML=$('#worksheet-content').innerHTML;close();window.print();main.innerHTML=old;render(true);break}case'session':sessionModal();break;case'session-done':{const s=state.sessions.find(x=>x.id===el.dataset.id);if(s)s.done=!s.done;save();render(true);break}case'session-remove':state.sessions=state.sessions.filter(x=>x.id!==el.dataset.id);save();render(true);break;case'calendar':exportCalendar();break;case'export':exportBackup();break;case'import':importFile();break;case'import-pack':importFile(true);break;case'export-pack':download('Study_Zone_Resource_Pack.json',JSON.stringify({app:'Study Zone resources',resources:state.resources.map(({title,subject,type,url,description})=>({title,subject,type,url,description}))},null,2));toast('Resource pack exported. Share the file with learners to import.');break;case'resource':resourceModal();break;case'remove-resource':state.resources=state.resources.filter(x=>x.id!==el.dataset.id);save();render(true);break;case'timer-preset':timer.run=false;timer.remaining=Number(el.dataset.minutes)*60;timer.total=timer.remaining;timer.kind='Focus';timer.credited=false;render(true);break;case'timer-break':timer.run=false;timer.remaining=300;timer.total=300;timer.kind='Break';timer.credited=false;render(true);break;case'timer-toggle':if(timer.run){timer.remaining=Math.max(0,Math.ceil((timer.end-Date.now())/1000));timer.run=false}else{if(timer.remaining===0){timer.remaining=timer.total;timer.credited=false}timer.end=Date.now()+timer.remaining*1000;timer.run=true}updateTimer();break;case'timer-reset':timer.run=false;timer.remaining=timer.total;timer.credited=false;updateTimer();break;case'quiet':document.body.classList.toggle('focus-view');el.textContent=document.body.classList.contains('focus-view')?'Return to full view':'Quiet view';break;case'breathe':{const orb=$('#breathe-orb');orb.classList.toggle('running');orb.textContent=orb.classList.contains('running')?'Gently in… and out.':'Take a moment';el.textContent=orb.classList.contains('running')?'Stop the guide':'Start the gentle guide';break}case'clear-data':modal(`<span class="eyebrow">A FRESH PAGE</span><h2>Clear this device’s study data?</h2><p>This removes your local notes, plan and progress. Export a backup first if you want to keep them.</p><div class="actions">${b('Export my work','export','','button secondary')}${b('Clear my data','confirm-clear','','button danger')}</div>`);break;case'confirm-clear':state=defaults();save();close();location.hash='home';render();toast('Your study space is ready for a fresh start.');break;}});
document.addEventListener('input',e=>{const el=e.target;switch(el.id){case'subject-search':filterSubjects();break;case'global-search':globalSearch(el.value);break;case'video-search':filterVideos();break;case'focus-task':state.profile.focusTask=el.value;save();break;}if(el.id.startsWith('lab-input-'))updateLab()});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.complete){const k=el.dataset.complete;state.completed=state.completed.filter(x=>x!==k);if(el.checked)state.completed.push(k);save();toast(el.checked?'A little progress, noticed.':'Topic ready for another look.')}if(el.dataset.setting){state.settings[el.dataset.setting]=el.checked;save();applySettings()}switch(el.id){case'subject-order':filterSubjects();break;case'practice-subject':location.hash='practice/'+el.value;break;case'practice-topic':location.hash=`practice/${el.dataset.subject}/${el.value}`;break;case'quiz-subject':quizIndex=0;location.hash='quiz/'+el.value;break;case'flash-subject':flashIndex=0;flashFlipped=false;location.hash='flashcards/'+el.value;break;case'video-subject':location.hash='videos/'+el.value;break;case'video-topic':filterVideos();break;case'paper-subject':case'paper-year':case'paper-number':filterPapers();break;case'specialisation':case'language-level':state.profile[el.dataset.subject]=el.value;save();break;}});
document.addEventListener('submit',e=>{const form=e.target;if(!['profile-form','answer-form','note-form','session-form','resource-form'].includes(form.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(form));switch(form.id){case'profile-form':state.profile.name=data.name.trim().slice(0,40);state.profile.goal=data.goal.trim().slice(0,160);save();close();render(true);toast('Your little space is ready.');break;case'answer-form':checkNumber(data.answer);break;case'note-form':{const n={id:form.dataset.id||uid(),title:data.title.trim(),subject:data.subject,body:data.body.trim(),date:today()};state.notes=state.notes.filter(x=>x.id!==n.id);state.notes.push(n);save();close();if(route[0]==='notebook')render(true);toast('Thought safely tucked away.');break}case'session-form':{const url=data.url?safeURL(data.url):'';if(data.url&&!url){toast('Use a complete http or https meeting link.');return}state.sessions.push({id:uid(),title:data.title.trim(),subject:data.subject,date:data.date,time:data.time,duration:Math.min(300,Math.max(5,Number(data.duration))),url,done:false});save();close();render(true);toast('A little time, set aside.');break}case'resource-form':{const url=safeURL(data.url);if(!url){toast('Use a complete http or https resource link.');return}state.resources.push({id:uid(),title:data.title.trim(),subject:data.subject,type:data.type,url,description:data.description.trim()});save();close();render(true);toast('Resource added to your personal pack.');break}}});
window.addEventListener('resize',syncMenu);
window.addEventListener('hashchange',()=>{if($('#dialog').open)close();render()});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#dialog').open){e.preventDefault();searchModal()}if(e.key==='Escape'){document.body.classList.remove('menu-open');$('.mobile-menu').setAttribute('aria-expanded','false');syncMenu()}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
function normalizeStudyState(raw){
 if(!raw||raw.version!==1||!raw.profile)throw Error('This is not a valid Study Zone study copy.');
 const next=defaults(),text=(v,max=200)=>typeof v==='string'?v.slice(0,max):'',id=v=>typeof v==='string'&&/^[a-zA-Z0-9:._-]{1,200}$/.test(v),date=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&Number.isFinite(new Date(v+'T12:00:00').getTime()),arr=k=>Array.isArray(raw[k])?raw[k]:[];
 next.profile={name:text(raw.profile.name,40),goal:text(raw.profile.goal,160),focusTask:text(raw.profile.focusTask,120)};
 for(const sub of subjects)if(typeof raw.profile[sub.id]==='string')next.profile[sub.id]=text(raw.profile[sub.id],80);
 next.pins=arr('pins').filter(x=>subject(x)).slice(0,63);
 next.completed=[...new Set(arr('completed').filter(k=>typeof k==='string'&&subjects.some(s=>s.topics.some(t=>key(s,t)===k))))];
 next.saved=arr('saved').filter(x=>x&&id(x.id)&&typeof x.url==='string'&&/^#(?:lesson|practice)\/[a-z0-9-]+\/[a-z0-9-]+(?:\/\d{1,2})?$/.test(x.url)&&subject(x.subject)).slice(0,1000).map(x=>({id:x.id,title:text(x.title,160),url:x.url,subject:x.subject}));
 next.notes=arr('notes').filter(x=>x&&id(x.id)&&typeof x.body==='string').slice(0,500).map(x=>({id:x.id,title:text(x.title,120),body:text(x.body,20000),subject:subject(x.subject)?x.subject:'',date:date(x.date)?x.date:today()}));
 next.sessions=arr('sessions').filter(x=>x&&id(x.id)&&date(x.date)&&/^([01]\d|2[0-3]):[0-5]\d$/.test(x.time)).slice(0,1000).map(x=>({id:x.id,title:text(x.title,100),subject:subject(x.subject)?x.subject:'',date:x.date,time:x.time,duration:Math.min(480,Math.max(5,Number(x.duration)||25)),url:safeURL(x.url)||'',done:x.done===true,...(id(x.shared_id)?{shared_id:x.shared_id}:{})}));
 next.scores=arr('scores').filter(x=>x&&subject(x.subject)&&typeof x.correct==='boolean').slice(-2000).map(x=>({key:text(x.key,200),subject:x.subject,correct:x.correct,date:date(x.date)?x.date:today()}));
 next.resources=arr('resources').filter(x=>x&&id(x.id)&&safeURL(x.url)).slice(0,500).map(x=>({id:x.id,title:text(x.title,140),subject:subject(x.subject)?x.subject:'',type:text(x.type,40),url:safeURL(x.url),description:text(x.description,600)}));
 next.visits=[...new Set(arr('visits').filter(date))].slice(-3660);next.focusMinutes=Math.min(1000000,Math.max(0,Number(raw.focusMinutes)||0));
 const prefs=raw.settings||{};next.settings={theme:prefs.theme==='dark'?'dark':'light',large:prefs.large===true,motion:prefs.motion===true,contrast:prefs.contrast===true};
 if(raw.last&&subject(raw.last.subject))next.last={subject:raw.last.subject,topic:topic(subject(raw.last.subject),raw.last.topic)?.id};return next;
}
const classroom=createClassroom({$,esc,link,b,head,modal,close,toast,subjects,download,getState:()=>state,exportBackup,render,
 applyState:value=>{state=normalizeStudyState(value);save();applySettings()},
 addSession:s=>{if(state.sessions.some(x=>x.shared_id===s.id)){toast('That session is already in your personal plan.');return}state.sessions.push({id:uid(),shared_id:s.id,title:s.title,subject:s.subject,date:s.date,time:s.time,duration:Math.min(480,s.duration),url:s.meeting_url,done:false});save();toast('Confirmed session added to your personal study plan.');}
});
setInterval(updateTimer,1000);
render();
classroom.init().catch(()=>toast('The shared classroom could not connect. Your included study tools are still available.'));
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
window.addEventListener('offline',()=>toast('You’re offline. Included lessons and tools are still here; external resources need a connection.'));
